<script setup lang="ts">
import { computed, onMounted, reactive, ref } from "vue";
import { Copy, KeyRound, LoaderCircle, MailPlus, Pencil, Trash2, X } from "lucide-vue-next";
import { useRoute } from "vue-router";
import ConfirmModal from "@/components/operations/ConfirmModal.vue";
import DataPanel from "@/components/operations/DataPanel.vue";
import OpsModal from "@/components/operations/OpsModal.vue";
import StatusBadge from "@/components/operations/StatusBadge.vue";
import { operationsRepository } from "@/data/repositories/operationsRepository";
import type { UiMemberRecord } from "@/data/models/operations";
import EducatorAccessModal from "@/components/operations/EducatorAccessModal.vue";

const route = useRoute(); const loading = ref(true); const saving = ref(false); const deleting = ref(false); const showForm = ref(false); const error = ref(""); const inviteToken = ref(""); const copied = ref(false); const members = ref<UiMemberRecord[]>([]); const editing = ref<UiMemberRecord | null>(null); const deleteTarget = ref<UiMemberRecord | null>(null);
const accessMember = ref<UiMemberRecord | null>(null); const activationKind = ref<"institute" | "educator">("institute");
const activationLink = computed(() => inviteToken.value ? `${window.location.origin}/${activationKind.value}/activate?token=${encodeURIComponent(inviteToken.value)}` : "");
const form = reactive({ email: "", role_slug: "institute_staff", expires_in_days: 7 }); const editForm = reactive({ position: "", status: "active", role_slug: "" }); const instituteId = () => Number(route.params.instituteId);
const teachers = computed(() => members.value.filter((member) => member.roleSlug === "teacher"));
async function load() { loading.value = true; error.value = ""; try { members.value = (await operationsRepository.members(instituteId(), { per_page: 100 })).items; } catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to load members."; } finally { loading.value = false; } }
async function invite() { saving.value = true; error.value = ""; try { if (form.role_slug === "teacher") { const response = await operationsRepository.inviteEducator({ email: form.email, role_slug: "teacher", institute_id: instituteId() }); inviteToken.value = response.invite_token; activationKind.value = "educator"; } else { const response = await operationsRepository.inviteMember(instituteId(), form); inviteToken.value = response.invite_token; activationKind.value = "institute"; } await load(); } catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to create invite."; } finally { saving.value = false; } }
function openEdit(member: UiMemberRecord) { editing.value = member; Object.assign(editForm, { position: member.position, status: member.status, role_slug: "" }); }
async function saveMember() { if (!editing.value) return; saving.value = true; try { await operationsRepository.updateMember(instituteId(), editing.value.userId, editForm); editing.value = null; await load(); } catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to update member."; } finally { saving.value = false; } }
async function copyToken() { await navigator.clipboard.writeText(activationLink.value); copied.value = true; window.setTimeout(() => { copied.value = false; }, 1500); }
async function confirmRemove() { if (!deleteTarget.value) return; deleting.value = true; try { await operationsRepository.removeMember(instituteId(), deleteTarget.value.userId); deleteTarget.value = null; await load(); } catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to remove member."; } finally { deleting.value = false; } }
function close() { showForm.value = false; inviteToken.value = ""; form.email = ""; } onMounted(load);
</script>

<template><div class="space-y-5"><div class="flex flex-wrap items-end justify-between gap-3"><div><p class="text-[12px] font-semibold uppercase tracking-[0.12em] text-blue">Team access</p><h2 class="mt-1 text-[26px] font-bold tracking-[-0.035em]">Members</h2><p class="mt-1 text-[13px] text-ink3">Invite administrators and staff into the institute context.</p></div><button class="ops-button-primary flex items-center gap-2 transition hover:-translate-y-0.5 hover:shadow-md" @click="showForm = true"><MailPlus :size="15" /> Invite member</button></div><p v-if="error" class="rounded-xl bg-pink-light px-4 py-3 text-[13px] text-pink">{{ error }}</p><DataPanel title="Member directory" :description="`${members.length} people`" :loading="loading" :empty="!members.length"><div class="overflow-x-auto"><table class="w-full min-w-[720px] text-left text-[12px]"><thead class="bg-bg-soft text-ink3"><tr><th class="px-5 py-3">Member</th><th class="px-4 py-3">Position</th><th class="px-4 py-3">Joined</th><th class="px-4 py-3">Status</th><th class="px-5 py-3 text-right">Actions</th></tr></thead><tbody class="divide-y divide-border"><tr v-for="member in members" :key="member.id" class="transition hover:bg-bg-soft/70"><td class="px-5 py-3.5"><p class="font-semibold">{{ member.name }}</p><p class="text-ink3">{{ member.email }}</p></td><td class="px-4 py-3.5 text-ink2">{{ member.position || 'Member' }}</td><td class="px-4 py-3.5 text-ink3">{{ member.joinedAt ? new Date(member.joinedAt).toLocaleDateString() : 'Pending' }}</td><td class="px-4 py-3.5"><StatusBadge :value="member.status" /></td><td class="px-5 py-3.5"><div class="flex justify-end gap-1"><button class="ops-icon-button" title="Edit member" @click="openEdit(member)"><Pencil :size="14" /></button><button class="ops-icon-button hover:bg-pink-light hover:text-pink" title="Remove member" @click="deleteTarget = member"><Trash2 :size="14" /></button></div></td></tr></tbody></table></div></DataPanel>
  <OpsModal :open="showForm" max-width="max-w-md" :close-on-backdrop="!saving" @close="close"><form class="rounded-2xl border border-border bg-bg-card p-5 shadow-2xl" @submit.prevent="invite"><div class="mb-5 flex justify-between"><div><h3 class="text-[17px] font-bold">Invite institute member</h3><p class="mt-1 text-[12px] text-ink3">Share the generated activation link using your approved channel.</p></div><button type="button" :disabled="saving" @click="close"><X :size="18" /></button></div><template v-if="!inviteToken"><div class="space-y-3"><label class="text-[11px] font-semibold">Email<input v-model="form.email" required type="email" class="ops-input" /></label><label class="text-[11px] font-semibold">Role<select v-model="form.role_slug" class="ops-input"><option value="institute_admin">Institute administrator</option><option value="institute_staff">Institute staff</option><option value="teacher">Teacher</option></select></label><label class="text-[11px] font-semibold">Expires in days<input v-model.number="form.expires_in_days" type="number" min="1" max="30" class="ops-input" /></label></div><div class="mt-5 flex justify-end gap-2"><button type="button" :disabled="saving" class="ops-button-secondary" @click="close">Cancel</button><button :disabled="saving" class="ops-button-primary inline-flex min-w-32 items-center justify-center gap-2"><LoaderCircle v-if="saving" :size="14" class="animate-spin" />{{ saving ? 'Creating…' : 'Create invite' }}</button></div></template><template v-else><div class="rounded-xl bg-mint-light p-4"><p class="text-[12px] font-semibold text-mint">Invite created</p><p class="mt-2 break-all font-mono text-[11px] text-ink2">{{ activationLink }}</p></div><button type="button" class="mt-4 flex w-full items-center justify-center gap-2 rounded-xl border border-border py-2.5 text-[12px] font-semibold transition hover:bg-bg-soft" @click="copyToken"><Copy :size="14" /> {{ copied ? 'Copied' : 'Copy activation link' }}</button></template></form></OpsModal>
  <OpsModal :open="Boolean(editing)" max-width="max-w-md" :close-on-backdrop="!saving" @close="editing = null"><form class="rounded-2xl border border-border bg-bg-card p-5 shadow-2xl" @submit.prevent="saveMember"><div class="mb-5 flex justify-between"><div><h3 class="text-[17px] font-bold">Edit member</h3><p class="mt-1 text-[12px] text-ink3">{{ editing?.name }}</p></div><button type="button" @click="editing = null"><X :size="18" /></button></div><div class="space-y-3"><label class="text-[11px] font-semibold">Position<input v-model="editForm.position" class="ops-input" placeholder="Teacher, Finance manager…" /></label><label class="text-[11px] font-semibold">Status<select v-model="editForm.status" class="ops-input"><option value="pending">Pending</option><option value="active">Active</option><option value="suspended">Suspended</option></select></label><label class="text-[11px] font-semibold">Role<select v-model="editForm.role_slug" class="ops-input"><option value="">Keep current role</option><option value="institute_admin">Institute administrator</option><option value="institute_staff">Institute staff</option><option value="teacher">Teacher</option></select></label></div><div class="mt-5 flex justify-end gap-2"><button type="button" class="ops-button-secondary" @click="editing = null">Cancel</button><button :disabled="saving" class="ops-button-primary inline-flex min-w-28 items-center justify-center gap-2"><LoaderCircle v-if="saving" :size="14" class="animate-spin" />{{ saving ? 'Saving…' : 'Update member' }}</button></div></form></OpsModal>
  <ConfirmModal :open="Boolean(deleteTarget)" title="Remove member?" :message="`Remove ${deleteTarget?.name || 'this member'} from the institute and revoke their institute role?`" confirm-label="Remove member" :busy="deleting" @close="deleteTarget = null" @confirm="confirmRemove" />
  <section v-if="teachers.length" class="rounded-2xl border border-border bg-bg-card p-5"><h3 class="text-[15px] font-bold">Teacher data access</h3><p class="mt-1 text-[12px] text-ink3">Grant class, course, student or subject visibility. Tutors are not available to institute admins.</p><div class="mt-4 grid gap-2 sm:grid-cols-2"><button v-for="teacher in teachers" :key="teacher.userId" class="flex items-center justify-between rounded-xl border border-border p-3 text-left transition hover:bg-bg-soft" @click="accessMember = teacher"><span><strong class="block text-[12px]">{{ teacher.name }}</strong><span class="text-[11px] text-ink3">{{ teacher.email }}</span></span><KeyRound :size="15" class="text-blue" /></button></div></section>
  <EducatorAccessModal :open="Boolean(accessMember)" :educator="accessMember ? { id: accessMember.userId, name: accessMember.name } : null" :institute-id="instituteId()" allow-parent-management @close="accessMember = null" />
</div></template>
